// Package: Polly
// Package: Microsoft.Extensions.AI

using Polly;
using Microsoft.Extensions.AI;

public sealed class ResilientAiClient
{
    private readonly IChatClient _chatClient;
    private readonly AsyncRetryPolicy<ChatResponse> _retryPolicy;
    private readonly AsyncTimeoutPolicy _timeoutPolicy;
    private readonly AsyncCircuitBreakerPolicy<HttpResponseMessage> _circuitBreaker;

    public ResilientAiClient(IChatClient chatClient)
    {
        _chatClient = chatClient;

        _retryPolicy = Policy<ChatResponse>
            .Handle<HttpRequestException>()
            .OrResult(r => r.Messages.Last().FinishReason == ChatFinishReason.RateLimit)
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                onRetry: (outcome, timespan, attempt, context) =>
                {
                    // Expected output: Retrying after rate limit, attempt 1 of 3
                    Console.WriteLine($"Retrying in {timespan.TotalSeconds}s (attempt {attempt})");
                    return Task.CompletedTask;
                });

        _timeoutPolicy = Policy.TimeoutAsync<ChatResponse>(TimeSpan.FromSeconds(30));

        _circuitBreaker = Policy<HttpResponseMessage>
            .Handle<HttpRequestException>()
            .CircuitBreakerAsync(
                handledEventsAllowedBeforeBreaking: 5,
                durationOfBreak: TimeSpan.FromMinutes(1),
                onBreak: (ex, breakDelay) =>
                {
                    // Expected output: Circuit opened due to repeated failures
                    Console.WriteLine($"Circuit broken for {breakDelay.TotalMinutes} minutes");
                    return Task.CompletedTask;
                },
                onReset: () =>
                {
                    Console.WriteLine("Circuit reset, resuming normal requests");
                    return Task.CompletedTask;
                });
    }

    public async Task<ChatResponse> GetResponseAsync(
        string prompt,
        CancellationToken ct = default)
    {
        // Combine timeout, retry, and circuit breaker
        return await _timeoutPolicy.ExecuteAsync(async ct2 =>
        {
            return await _retryPolicy.ExecuteAsync(async ct3 =>
            {
                var response = await _chatClient.GetResponseAsync(
                    new[] { new ChatMessage(ChatRole.User, prompt) },
                    cancellationToken: ct3);

                // Expected output: Successful response returned on first attempt
                return response;
            }, ct2);
        }, ct);
    }
}

// Sample usage
var resilientClient = new ResilientAiClient(
    new OpenAIClient("your-api-key").AsChatClient("gpt-4o-mini"));

try
{
    var response = await resilientClient.GetResponseAsync(
        "Explain load balancing in ASP.NET Core.");
    Console.WriteLine(response.Messages.Last().Text);
}
catch (TimeoutRejectedException)
{
    Console.WriteLine("Request timed out after 30 seconds");
}
catch (BrokenCircuitException)
{
    Console.WriteLine("Circuit breaker is open, try again later");
}
